def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One scripted interaction against `holder`'s function; every launcher seam wrapped on `t`, recorded; the account lookup stood in."""
    import contextlib, dataclasses, pwd
    from types import SimpleNamespace
    transcript: list = []
    calls: list = []
    script = list(spec.get("answers", []))

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            # A field or a schema by what it asks (the transcript shows how it is rendered), a choice by its value.
            kind = type(value).__name__
            if kind == "Field":
                return {kind: f"{value.name}: {value.title}"}
            if kind == "Schema":
                return {kind: [f"{f.name}: {f.title}" for f in value.fields]}
            if kind == "Choice":
                return {kind: value.value}
            return {kind: {f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if isinstance(value, SimpleNamespace):
            return "NAMESPACE"
        if isinstance(value, (str, int, float, bool)) or value is None:
            return value
        if callable(value):
            return "CALLABLE"
        return repr(value)

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    def ask(prompt):
        transcript.append(["ask", prompt])
        if len(transcript) > 400:
            raise AssertionError("the prompt did not stop asking")
        return script.pop(0) if script else ""

    def show(line):
        transcript.append(["show", line])

    class Stdout:
        def write(self, text):
            if text.strip():
                transcript.append(["stdout", text.rstrip("\n")])
            return len(text)

        def flush(self):
            pass

    def runner(argv, **kwargs):
        note("runner", list(argv), **kwargs)
        if list(argv)[-1:] != ["models"]:
            raise AssertionError(f"the runner was asked something no case expects: {argv}")
        shape = spec.get("runner")
        if shape == "oserror":
            raise OSError(2, "No such file or directory")
        if shape == "rc":
            return SimpleNamespace(returncode=1, stdout="", stderr="not signed in")
        return SimpleNamespace(returncode=0, stdout={"ok": "syrd422-pro  the owner's best\nsyrd422-flash\n\nsyrd422-pro again\n"}.get(shape, "\n"), stderr="")

    def getpwnam(user):
        note("pwd.getpwnam", user)
        if spec.get("exists") and user == OWNER:
            return SimpleNamespace(pw_name=user)
        raise KeyError(f"getpwnam(): name not found: {user!r}")

    class Recorded:
        """A module read through the launcher, its functions recorded as they are called."""

        def __init__(self, name, real, overrides):
            self._name, self._real, self._overrides = name, real, overrides

        def __getattr__(self, attr):
            value = self._overrides.get(attr, getattr(self._real, attr))
            if callable(value) and not isinstance(value, type):
                def wrapped(*args, _attr=attr, _value=value, **kwargs):
                    note(f"{self._name}.{_attr}", *args, **kwargs)
                    return _value(*args, **kwargs)
                return wrapped
            return value

    seams = ("_validate_new_project_implementer_role", "_prompt_bool", "_runtime_field", "_model_field", "_effort_field", "RoleSelection",
             "Schema", "Field", "Choice")
    names = [*FUNCTIONS, *seams, "_owner_command_env_args", "terminal_select", "runtime_catalog", "NEW_PROJECT_ROLE_CLI_DEFAULTS",
             "NEW_PROJECT_DEFAULT_IMPLEMENTER_ROLES", "NEW_PROJECT_CONVENTIONAL_IMPLEMENTER_ROLES"]
    saved = {n: getattr(t, n) for n in names}
    saved_getpwnam = pwd.getpwnam
    try:
        under = {n: getattr(holder, n) for n in FUNCTIONS}
        on_launcher = {}
        for n in (*FUNCTIONS, *seams):
            def passthrough(*args, _n=n, **kwargs):
                note(_n, *args, **kwargs)
                return saved[_n](*args, **kwargs)
            on_launcher[n] = passthrough
        on_launcher["_owner_command_env_args"] = lambda user, home, command: note("_owner_command_env_args", user, str(home), command) or ["OWNER-PREFIX", user, *command]
        overrides = {"select_many": lambda *a, **k: spec["select_many"]} if "select_many" in spec else {}
        on_launcher["terminal_select"] = Recorded("terminal_select", saved["terminal_select"], overrides)
        on_launcher["runtime_catalog"] = Recorded("runtime_catalog", saved["runtime_catalog"], {})
        on_launcher.update(spec.get("launcher", {}))
        for n, f in on_launcher.items():
            setattr(t, n, f)
        pwd.getpwnam = getpwnam
        call = spec["call"]
        try:
            with contextlib.redirect_stdout(Stdout()):
                if call == "plan":
                    kwargs = {"input_func": ask, "print_func": show}
                    if "runner" in spec:
                        kwargs["runner"] = runner
                    if "owner" in spec:
                        kwargs["owner_user"] = spec["owner"]
                    if spec.get("home"):
                        from pathlib import Path as _Path
                        kwargs["owner_home"] = _Path(HOME)
                    got = under["_prompt_switchyard_role_plan"](**kwargs)
                elif call == "runtime":
                    kwargs = {"default_cli": spec["default_cli"], "input_func": ask, "print_func": show}
                    if "configured" in spec:
                        role, cli, model, effort = spec["configured"]
                        kwargs["configured"] = saved["RoleSelection"](role=role, cli=cli, model=model, effort=effort)
                    if "runner" in spec:
                        kwargs["runner"] = runner
                    for key in ("owner_args", "unverified_because", "interactive"):
                        if key in spec:
                            kwargs[key] = spec[key]
                    got = under["_prompt_role_runtime_plan"](spec["role"], **kwargs)
                elif call == "choices":
                    got = under["_prompt_switchyard_role_choices"](input_func=ask, print_func=show)
                elif call == "field":
                    field = under["_implementer_roles_field"]()
                    verdicts = {}
                    for value in ("main", " Main ", "qa", "audit", "director", "user", "unassigned", "designer", "9bad", "Bad Role", "a" * 64, "a" * 65, ""):
                        try:
                            verdicts[value] = field.validate(value)
                        except SystemExit as exc:
                            verdicts[value] = {"refused": str(exc)}
                    got = {"type": type(field).__name__, "name": field.name, "kind": field.kind, "title": field.title,
                           "choices": [[c.value, c.display, c.description, c.unlisted] for c in field.choices_for({})], "default": field.default,
                           "allow_custom": field.allow_custom, "custom_title": field.custom_title, "required": field.required, "description": field.description,
                           "depends_on": field.depends_on, "secret": field.secret, "validate": verdicts}
                else:
                    got = under["_owner_account_exists"](spec["user"])
            answer = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            answer = {"raised": type(exc).__name__, "message": norm(str(exc))}
        return {"answer": answer, "transcript": transcript, "calls": calls, "unused answers": script}
    finally:
        pwd.getpwnam = saved_getpwnam
        for n, f in saved.items():
            setattr(t, n, f)
# ----------------------------------------------------------------------------------------------------------------------


def check(condition: bool, detail: str) -> None:
    global CHECKS
    assert condition, detail
    CHECKS += 1


def python(probe: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "-c", probe], cwd=ROOT, capture_output=True, text=True,
                          env={"PATH": "/usr/bin:/bin"}, check=False)


class patched:
    def __init__(self, target: object, **values: object) -> None:
        self.target, self.values = target, values

    def __enter__(self) -> None:
        self.saved = {name: getattr(self.target, name) for name in self.values}
        for name, value in self.values.items():
            setattr(self.target, name, value)

    def __exit__(self, *exc: object) -> None:
        for name, value in self.saved.items():
            setattr(self.target, name, value)


def refuse(what: str):
    def refused(*args: object, **kwargs: object) -> object:
        raise AssertionError(f"{what} was called: {args} {kwargs}")
    return refused


EXECS = ("execv", "execve", "execvp", "execvpe", "execl", "execle", "execlp", "execlpe")


class contained:
    """Spawns, every exec, signals, connections and real account/group lookups refused."""

    def __enter__(self) -> None:
        self.parts = [patched(subprocess, run=refuse("subprocess.run"), Popen=refuse("subprocess.Popen")),
                      patched(os, kill=refuse("os.kill"), system=refuse("os.system"), **{name: refuse(f"os.{name}") for name in EXECS}),
                      patched(pwd, getpwnam=refuse("pwd.getpwnam"), getpwuid=refuse("pwd.getpwuid")),
                      patched(grp, getgrgid=refuse("grp.getgrgid"), getgrnam=refuse("grp.getgrnam")),
                      patched(socket.socket, connect=refuse("socket.connect"), connect_ex=refuse("socket.connect_ex"))]
        for part in self.parts:
            part.__enter__()

    def __exit__(self, *exc: object) -> None:
        for part in reversed(self.parts):
            part.__exit__(*exc)


def run(holder: object, spec: dict) -> dict:
    with contained():
        return json.loads(json.dumps(run_case(t, holder, spec, REACHED)))


def test_the_guard_itself_refuses_a_spawn_an_exec_a_lookup_and_a_connection() -> None:
    attempts = [lambda: subprocess.run(["true"]), lambda: subprocess.Popen(["true"]), lambda: os.kill(os.getpid(), 0), lambda: os.system("true"),
                lambda: pwd.getpwuid(0), lambda: grp.getgrgid(0), lambda: socket.socket().connect(("127.0.0.1", 9)),
                *(lambda name=name: getattr(os, name)("true", ["true"]) for name in EXECS)]
    for attempt in attempts:
        with contained():
            try:
                attempt()
            except AssertionError as exc:
                refused = " was called: " in str(exc)
            else:
                refused = False
        check(refused, "the guard refuses a spawn, every exec, a signal, an account or group lookup and a connection")


